// ─── Compute SimHash for text-only questions ─────────────────────────────────

function simHash(text, bits = 64) {
  const tokens = text
    .toLowerCase()
    .replace(/[^\w\s]/g, '')   // strip punctuation
    .split(/\s+/)
    .filter(Boolean);

  if (tokens.length === 0) {
    // Edge case: empty/whitespace-only question
    return '0'.repeat(bits);
  }

  const vector = new Array(bits).fill(0);

  for (const token of tokens) {
    // djb2 hash
    let h = 5381;
    for (let i = 0; i < token.length; i++) {
      h = ((h << 5) + h) ^ token.charCodeAt(i);
      h = h >>> 0; // unsigned 32-bit
    }
    // Project onto 64-bit vector
    for (let b = 0; b < bits; b++) {
      vector[b] += (h >> (b % 32)) & 1 ? 1 : -1;
    }
  }

  return vector.map(v => (v >= 0 ? '1' : '0')).join('');
}

